context.source_term_tool_snapshot:
from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path
from typing import Any

from .records import RecordError, PLACEHOLDER_TOKEN_RE, expected_unit_hashes, is_font_wrapper, load_jsonl, load_upstream_commit, restore_placeholders, sha256_value, term_display_text
from .schema_validation import validate_named_schema
from .terminology import load_approved_term_pairs


def _space(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def source_tex_hash(unit: dict[str, Any]) -> str:
    return sha256_value(unit["render"]["prefix"] + restore_placeholders(unit, unit["source_text"]) + unit["render"]["suffix"])


def source_projection(unit: dict[str, Any]) -> tuple[str, list[str]]:
    """Expose prose through formatting wrappers without reading protected math."""
    source = unit["source_text"]
    pieces: list[str] = []
    declarations: list[str] = []
    opened: dict[tuple[str, str], tuple[int, str]] = {}
    cursor = 0
    for match in PLACEHOLDER_TOKEN_RE.finditer(source):
        pieces.append(source[cursor:match.start()])
        name, number = match.group(1).rsplit("_", 1)
        if name.endswith("OPEN") or name.endswith("CLOSE"):
            base = name.removesuffix("OPEN").removesuffix("CLOSE")
            if base in {"TEXTIT", "EMPH"}:
                key = (base, number)
                if name.endswith("OPEN") and is_font_wrapper(match.group(0), unit["placeholders"]):
                    prefix = "".join(pieces)
                    opened[key] = (len(prefix), prefix)
                elif name.endswith("CLOSE") and key in opened and is_font_wrapper(match.group(0), unit["placeholders"]):
                    start, prefix = opened.pop(key)
                    body = "".join(pieces)[start:]
                    # A complete restored paragraph can contain several
                    # sentences. A later "is defined" must not retroactively
                    # turn an earlier editorial emphasis into a named concept.
                    # Structural item/paragraph and footnote boundaries also
                    # prevent a following bibliographic description from
                    # declaring the preceding italic paper title as a term.
                    boundary = r"[.!?;]|<(?:STRUCT|FOOTNOTEOPEN|FOOTNOTECLOSE)_[0-9]{4}>"
                    before = re.split(boundary, prefix)[-1]
                    after = re.split(boundary, source[match.end():])[0]
                    introduced = (unit.get("node_kind") == "definition"
                                  or bool(re.search(r"\b(?:call|calls|called|calling|say|says|said|define|defines|defined|defining)\b",
                                                    before + " " + after, re.IGNORECASE)))
                    # An italic imperative with mathematical arguments quotes
                    # wording to use, rather than naming a lexical concept.
                    # Its prose remains visible to the ordinary catalog scan.
                    visible_body = term_display_text(body, unit["placeholders"])
                    usage_clause = (re.match(r"^(?:let|assume|suppose)\b", _space(visible_body), re.IGNORECASE)
                                    and PLACEHOLDER_TOKEN_RE.search(visible_body))
                    # Math-qualified declarations still expose their prose parts.
                    for phrase in ([] if usage_clause or not introduced else PLACEHOLDER_TOKEN_RE.split(visible_body)[::2]):
                        phrase = _space(phrase).strip(" -.,:;`'\"()")
                        if PLACEHOLDER_TOKEN_RE.search(visible_body):
                            # A formula can leave a connector as a whole prose
                            # part, with no lexical concept before it.
                            phrase = re.sub(r"(?:^|\s+)(?:of|over|in|between|with|to|on|from)$", "", phrase, flags=re.IGNORECASE)
                        if phrase and re.search(r"[A-Za-z]", phrase):
                            declarations.append(phrase)
            if not is_font_wrapper(match.group(0), unit["placeholders"]):
                # Footnotes and other semantic wrappers are boundaries; their
                # prose is scanned, but phrases cannot bridge those boundaries.
                pieces.append(match.group(0))
        else:
            pieces.append(match.group(0))
        cursor = match.end()
    pieces.append(source[cursor:])
    text = _space(term_display_text("".join(pieces), unit["placeholders"]))
    # Articles and trailing connectors belong to the surrounding sentence;
    # protected formulas supply qualifiers outside the exposed lexical core.
    declarations = [re.sub(r"^(?:a|an|the)\s+", "", phrase, flags=re.IGNORECASE) for phrase in declarations]
    return text, sorted(set(declarations))


def _matches(text: str, phrase: str, *, ignore_case: bool = False):
    expression = r"(?<![\w])" + re.escape(_space(phrase)) + r"(?![\w])"
    return list(re.finditer(expression, text, re.IGNORECASE if ignore_case else 0))


def _assignment_set(text: str, match: re.Match[str]) -> bool:
    if match.group(0).casefold() != "set" or not re.match(r"\s+<MATH_[0-9]{4}>", text[match.end():]):
        return False
    before = text[:match.start()].rstrip()
    return (not before or before[-1] in ".!?"
            or bool(re.search(r"\b(?:us|can|could|may|must|shall|will|and)\s*$", before, re.IGNORECASE))
            or bool(re.search(r"\bwe(?:\s+(?:now|first|then|finally|similarly))*\s*$", before, re.IGNORECASE))
            or bool(re.search(r"(?:^|[.!?]\s+)(?:for (?:every|each)\b[^.!?]*|finally|similarly),$", before, re.IGNORECASE)))


def load_catalog(root: Path) -> dict[str, Any]:
    path = root / "config/source-terms.json"
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise RecordError(f"cannot read source term catalog: {exc}") from exc
    errors = validate_named_schema(value, "source-terms.schema.json", str(path))
    if errors:
        raise RecordError("\n".join(errors))
    seen_ids: set[str] = set()
    seen_forms: set[str] = set()
    for entry in value["terms"]:
        if not entry["forms"] or not entry["evidence"]:
            raise RecordError("source term catalog requires forms and source evidence")
        if entry["id"] in seen_ids:
            raise RecordError("duplicate source term concept ID")
        seen_ids.add(entry["id"])
        for form in entry["forms"]:
            key = _space(form).casefold()
            if key in seen_forms or form != _space(form):
                raise RecordError(f"duplicate or noncanonical source term form: {form}")
            if PLACEHOLDER_TOKEN_RE.search(form) or re.search(r"[\\{}$%]", form):
                raise RecordError("catalog forms must be exposed prose, not protected TeX")
            seen_forms.add(key)
    scopes = value.get("nonmathematical_chapters", [])
    if len({scope["chapter"] for scope in scopes}) != len(scopes):
        raise RecordError("duplicate nonmathematical chapter scope")
    uses = value.get("nonmathematical_occurrences", [])
    if any(use["occurrence_index"] < 0 for use in uses):
        raise RecordError("nonmathematical occurrence index must be nonnegative")
    keys = {(use["chapter"], use["source_tex_hash"], use["source_term"], use["occurrence_index"]) for use in uses}
    if len(keys) != len(uses):
        raise RecordError("duplicate nonmathematical source occurrence")
    return value


def source_inventory(unit: dict[str, Any], catalog: dict[str, Any]) -> dict[str, Any]:
    """Requirements depend only on source nodes and the explicit catalog scope."""
    if any(unit.get(key) != expected for key, expected in expected_unit_hashes(unit).items()):
        raise RecordError(f"{unit['unit_id']}: source inventory refuses stale unit hashes")
    text, declarations = source_projection(unit)
    matches = []
    nonmathematical = unit["chapter"] in {scope["chapter"] for scope in catalog.get("nonmathematical_chapters", [])}
    excluded_spans = set()
    uses = [use for use in catalog.get("nonmathematical_occurrences", []) if use["chapter"] == unit["chapter"]]
    tex_hash = source_tex_hash(unit) if uses else None
    for use in uses:
        if use["source_tex_hash"] == tex_hash:
            occurrences = _matches(text, use["source_term"])
            if use["occurrence_index"] < 0 or use["occurrence_index"] >= len(occurrences):
                raise RecordError("nonmathematical source occurrence no longer exists")
            excluded_spans.add(occurrences[use["occurrence_index"]].span())
    for entry in ([] if nonmathematical else catalog["terms"]):
        if entry["chapters"] and unit["chapter"] not in entry["chapters"]:
            continue
        for form in entry["forms"]:
            for match in _matches(text, form, ignore_case=True):
                if match.span() in excluded_spans or _assignment_set(text, match):
                    continue
                matches.append((match.start(), match.end(), entry["id"], "catalog"))
    exclusions = {phrase.casefold() for phrase in catalog["nonmathematical_declarations"]}
    for declaration in ([] if nonmathematical else declarations):
        if declaration.casefold() in exclusions:
            continue
        for match in _matches(text, declaration):
            if match.span() in excluded_spans:
                continue
            matches.append((match.start(), match.end(), declaration, "source-declaration"))
    # Longest phrases win; nested generic words are not double-counted.
    matches.sort(key=lambda item: (item[0], -(item[1] - item[0]), item[3], item[2]))
    occurrences = []
    end = -1
    for start, stop, concept, rule in matches:
        if start < end:
            continue
        occurrences.append({"source_term": text[start:stop], "projection_start": start,
                            "projection_end": stop, "concept": concept, "rule": rule})
        end = stop
    return {"unit_id": unit["unit_id"], "source_commit": unit["source_commit"],
            "source_text_hash": unit["source_text_hash"],
            "source_structure_hash": unit["source_structure_hash"],
            "catalog_hash": sha256_value(catalog), "occurrences": occurrences}


def validate_source_terms(unit: dict[str, Any], candidate: dict[str, Any], catalog: dict[str, Any], approved: set[tuple[str, str]] | None = None) -> list[str]:
    uid = unit["unit_id"]
    inventory = source_inventory(unit, catalog)
    source, _ = source_projection(unit)
    declarations = candidate.get("term_occurrences")
    if not isinstance(declarations, list):
        return [f"{uid}: term_occurrences must be an array"]
    errors: list[str] = []
    valid = []
    unknown = candidate.get("unknown_terms")
    translation = candidate.get("translation")
    if not isinstance(unknown, list) or not isinstance(translation, str):
        return [f"{uid}: unknown_terms must be an array and translation a string"]
    pending = {(item["source_term"], item["target_term"]) for item in unknown
               if isinstance(item, dict) and all(isinstance(item.get(field), str) and item[field].strip()
                                                for field in ("source_term", "target_term", "context"))}
    target_cursor = 0
    for index, declaration in enumerate(declarations):
        if not isinstance(declaration, dict) or any(not isinstance(declaration.get(field), str) or not declaration[field].strip() for field in ("source_term", "target_term")):
            errors.append(f"{uid}: malformed term occurrence {index}")
            continue
        english, chinese = declaration["source_term"], declaration["target_term"]
        if (english, chinese) not in (approved or set()):
            if (english, chinese) not in pending or candidate.get("term_status") != "DECISION_REQUIRED":
                errors.append(f"{uid}: unapproved term lacks pending contextual evidence: {english}")
        literal = term_display_text(f"{chinese}（{english}）", unit["placeholders"])
        position = term_display_text(translation, unit["placeholders"]).find(literal, target_cursor)
        if position < 0:
            errors.append(f"{uid}: missing or repeated bilingual display: {literal}")
        else:
            target_cursor = position + len(literal)
        valid.append((index, _space(term_display_text(english, unit["placeholders"]))))
    # Longer phrases receive source spans first, so a later short word cannot
    # consume the source of an earlier compound. Counts and case stay exact.
    assigned: list[tuple[int, int, str]] = []
    for index, english in sorted(valid, key=lambda item: (-len(item[1]), item[0])):
        available = [match for match in _matches(source, english)
                     if not any(match.start() < stop and start < match.end() for start, stop, _ in assigned)]
        # An ordinary use may precede the same mathematical word. Allocate the
        # required source occurrence first, while allowing optional displays
        # for the remaining ordinary uses without reusing any source span.
        core = re.sub(r"^(?:a|an|the) ", "", english, flags=re.IGNORECASE)
        available.sort(key=lambda match: not any(match.start() <= item["projection_start"] and item["projection_end"] <= match.end()
                                                and core == item["source_term"] for item in inventory["occurrences"]))
        if not available:
            errors.append(f"{uid}: declared term has no unused exact source occurrence: {english}")
            continue
        match = available[0]
        assigned.append((match.start(), match.end(), english))
    missing = Counter(item["source_term"] for item in inventory["occurrences"]
                      if not any(start <= item["projection_start"] and item["projection_end"] <= stop
                                 and (english == item["source_term"] or re.sub(r"^(?:a|an|the) ", "", english, flags=re.IGNORECASE) == item["source_term"])
                                 for start, stop, english in assigned))
    for english, count in sorted(missing.items()):
        errors.append(f"{uid}: missing source-side term coverage ({count}): {english}")
    return errors


def audit_repository_terms(root: Path, harvest: Path | None = None) -> tuple[dict[str, Any], list[str]]:
    catalog = load_catalog(root)
    approved = load_approved_term_pairs(root / "config/glossary.yml")
    source_commit = load_upstream_commit(root / "upstream.lock")
    if catalog["source_commit"] != source_commit:
        raise RecordError("source term catalog uses a different locked source commit")
    units = {}
    batches = {}
    for path in sorted((root / "translation-data/units").glob("*.jsonl")):
        rows = load_jsonl(path)
        for row in rows:
            if row["unit_id"] in units:
                raise RecordError(f"duplicate active source unit: {row['unit_id']}")
            if row["source_commit"] != source_commit:
                raise RecordError(f"different source commit: {row['unit_id']}")
            units[row["unit_id"]] = row
        batches[path.stem] = rows
    # Evidence is English source, never a candidate's term metadata.
    errors = []
    by_tex = {}
    for row in units.values():
        by_tex.setdefault((row["chapter"], source_tex_hash(row)), []).append(row)
    containers = None
    locked_evidence = []
    for entry in catalog["terms"]:
        for evidence in entry["evidence"]:
            if evidence.get("kind") == "locked-source-container":
                check = {"concept": entry["id"], **evidence, "status": "FAIL"}
                try:
                    if (evidence["source_commit"] != source_commit
                            or evidence["selector"]["file"] != evidence["chapter"] + ".tex"):
                        raise RecordError("catalog evidence commit/chapter differs from locked source")
                    if evidence["source_term"].casefold() not in {form.casefold() for form in entry["forms"]}:
                        raise RecordError("catalog evidence word is not a declared form")
                    if containers is None:
                        from .source_containers import Containers
                        containers = Containers(root, harvest)
                    selected = containers.select(evidence["selector"])
                    if evidence["fragment_hash"] != selected["location"]["fragment_hash"]:
                        raise RecordError("catalog evidence full locked-Git fragment hash differs")
                    if not _matches(source_projection(selected["inventory_unit"])[0], evidence["source_term"]):
                        raise RecordError("catalog evidence word is absent from exposed locked-Git prose")
                    check.update(status="PASS", blob_oid=selected["blob_oid"],
                                 blob_hash=selected["blob_hash"], location=selected["location"])
                except (RecordError, OSError) as exc:
                    check["error"] = str(exc)
                    errors.append(f"{entry['id']}: locked catalog evidence: {exc}")
                locked_evidence.append(check)
                continue
            rows = by_tex.get((evidence["chapter"], evidence["source_tex_hash"]), [])
            if (not any(_matches(source_projection(row)[0], evidence["source_term"]) for row in rows)
                    or evidence["source_term"].casefold() not in {form.casefold() for form in entry["forms"]}):
                errors.append(f"{entry['id']}: catalog evidence is absent from current English source")
    for scope in catalog.get("nonmathematical_chapters", []):
        evidence = scope["title_evidence"]
        rows = by_tex.get((scope["chapter"], evidence["source_tex_hash"]), [])
        if not any(row["node_kind"] == "chapter_title" and source_projection(row)[0] == evidence["source_title"] for row in rows):
            errors.append(f"{scope['chapter']}: nonmathematical chapter lacks its locked English title evidence")
    for use in catalog.get("nonmathematical_occurrences", []):
        rows = by_tex.get((use["chapter"], use["source_tex_hash"]), [])
        if not any(len(_matches(source_projection(row)[0], use["source_term"])) > use["occurrence_index"] for row in rows):
            errors.append(f"{use['chapter']}: nonmathematical occurrence lacks its locked English source evidence")
    report = {"schema_version": 1, "source_commit": source_commit,
              "catalog_hash": sha256_value(catalog), "unit_count": len(units),
              "batch_count": len(batches), "required_occurrences": 0, "units": [], "candidates": [],
              "locked_catalog_evidence": locked_evidence}
    for row in units.values():
        inventory = source_inventory(row, catalog)
        report["units"].append(inventory)
        report["required_occurrences"] += len(inventory["occurrences"])
    for path in sorted((root / "translation-data/candidates").glob("*/*.jsonl")):
        rows = load_jsonl(path)
        if path.stem not in batches or Counter(row["unit_id"] for row in rows) != Counter(row["unit_id"] for row in batches.get(path.stem, [])):
            errors.append(f"{path.relative_to(root)}: candidate batch does not exactly cover its source units")
        for candidate in rows:
            row = units.get(candidate["unit_id"])
            findings = ([f"unknown source unit: {candidate['unit_id']}"] if row is None
                        else validate_source_terms(row, candidate, catalog, approved))
            report["candidates"].append({"path": str(path.relative_to(root)),
                                         "unit_id": candidate["unit_id"], "errors": findings})
            errors.extend(findings)
    candidate_stems = {path.stem for path in (root / "translation-data/candidates").glob("*/*.jsonl")}
    for stem in sorted(set(batches) - candidate_stems):
        errors.append(f"{stem}: source batch has no candidate coverage")
    return report, errors

context.term_display_tool_snapshot:
from __future__ import annotations

import hashlib
import json
import re
import unicodedata
from pathlib import Path
from typing import Any, Iterable, Mapping

from .schema_validation import validate_named_schema


HASH_RE = re.compile(r"^sha256:[0-9a-f]{64}$")
PLACEHOLDER_NAME_RE = re.compile(r"^[A-Z][A-Z0-9]*_[0-9]{4}$")
PLACEHOLDER_TOKEN_RE = re.compile(r"<([A-Z][A-Z0-9]*_[0-9]{4})>")
ASCII_WORD_RE = re.compile(r"(?<![A-Za-z])[A-Za-z][A-Za-z.-]*(?![A-Za-z])")
MODEL_LANE_RE = re.compile(r"^[A-Za-z0-9._-]+$")
STAGES = (
    "AI_DRAFT",
    "STRUCTURE_OK",
    "TERM_OK",
    "CRITIC_OK",
    "LANGUAGE_REVIEWED",
    "MATH_REVIEWED",
    "PUBLISHED",
)
MODEL_MAX_STAGE = STAGES.index("CRITIC_OK")


class RecordError(ValueError):
    """Raised when structured translation data violates a hard constraint."""


def normalize_text(value: str) -> str:
    value = value.replace("\r\n", "\n").replace("\r", "\n")
    return unicodedata.normalize("NFC", value).strip()


def canonical_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sha256_value(value: Any) -> str:
    payload = value if isinstance(value, str) else canonical_json(value)
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def expected_unit_hashes(unit: dict[str, Any]) -> dict[str, str]:
    source_text = normalize_text(_require_string(unit, "source_text"))
    structure = {
        "node_kind": unit.get("node_kind"),
        "parent_tag": unit.get("parent_tag"),
        "placeholders": unit.get("placeholders", {}),
        "render": unit.get("render", {}),
    }
    math_nodes = {
        key: value
        for key, value in sorted(unit.get("placeholders", {}).items())
        if key.startswith("MATH_")
    }
    extra = {}
    if unit.get('schema_version') in {2,3}:
        from .math_text import complete_math_nodes, skeleton
        structure['math_text_regions'] = unit['math_text_regions']
        math_nodes = complete_math_nodes(unit)
        extra['source_math_skeleton_hash'] = sha256_value(skeleton(unit))
    return {
        "source_text_hash": sha256_value(source_text),
        "source_structure_hash": sha256_value(structure),
        "source_math_hash": sha256_value(math_nodes),
        **extra,
    }


def stamp_unit_hashes(unit: dict[str, Any]) -> dict[str, Any]:
    stamped = dict(unit)
    stamped.update(expected_unit_hashes(stamped))
    return stamped


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        raise RecordError(f"cannot read {path}: {exc}") from exc
    for line_number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise RecordError(f"{path}:{line_number}: invalid JSON: {exc.msg}") from exc
        if not isinstance(value, dict):
            raise RecordError(f"{path}:{line_number}: each JSONL row must be an object")
        value["_record_location"] = f"{path}:{line_number}"
        records.append(value)
    if not records:
        raise RecordError(f"{path}: no records")
    return records


def write_jsonl(path: Path, records: Iterable[dict[str, Any]]) -> None:
    rows = []
    for record in records:
        clean = {key: value for key, value in record.items() if not key.startswith("_")}
        rows.append(json.dumps(clean, ensure_ascii=False, sort_keys=True))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(rows) + "\n", encoding="utf-8")


def load_upstream_commit(path: Path) -> str:
    try:
        import tomllib

        value = tomllib.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise RecordError(f"cannot read upstream lock {path}: {exc}") from exc
    commit = value.get("commit")
    if not isinstance(commit, str) or not re.fullmatch(r"[0-9a-f]{40}", commit):
        raise RecordError(f"{path}: commit must be a full lowercase Git SHA-1")
    return commit


def validate_records(
    units: list[dict[str, Any]],
    candidates: list[dict[str, Any]],
    source_commit: str,
) -> list[str]:
    errors: list[str] = []
    unit_by_id: dict[str, dict[str, Any]] = {}
    for unit in units:
        unit_id = unit.get("unit_id")
        location = unit.get("_record_location", "unit")
        if not isinstance(unit_id, str) or not unit_id:
            errors.append(f"{location}: missing non-empty unit_id")
            continue
        if unit_id in unit_by_id:
            errors.append(f"{location}: duplicate unit_id {unit_id}")
            continue
        unit_by_id[unit_id] = unit
        errors.extend(_validate_unit(unit, source_commit))

    candidate_ids: set[str] = set()
    for candidate in candidates:
        unit_id = candidate.get("unit_id")
        location = candidate.get("_record_location", "candidate")
        if not isinstance(unit_id, str) or not unit_id:
            errors.append(f"{location}: missing non-empty unit_id")
            continue
        if unit_id in candidate_ids:
            errors.append(f"{location}: duplicate candidate unit_id {unit_id}")
            continue
        candidate_ids.add(unit_id)
        unit = unit_by_id.get(unit_id)
        if unit is None:
            errors.append(f"{location}: candidate references unknown unit {unit_id}")
            continue
        errors.extend(_validate_candidate(candidate, unit, source_commit))

    missing = sorted(set(unit_by_id) - candidate_ids)
    if missing:
        errors.append("candidate file does not cover units: " + ", ".join(missing))
    return errors


def restore_placeholders(
    unit: dict[str, Any],
    translation: str,
    overrides: Mapping[str, str] | None = None,
    *,
    delimit_commands: bool = False,
) -> str:
    if unit.get('schema_version') in {2,3}:
        from .math_text import validate_translation
        errors = validate_translation(unit, translation)
        if errors:
            raise RecordError('\n'.join(errors))
        if overrides and any(name.startswith('MATHSEG_') and value != unit['placeholders'].get(name)
                             for name, value in overrides.items()):
            raise RecordError('typed math locked pieces cannot be overridden during restoration')
    rendered = translation
    for name in placeholder_names(unit.get("source_text", "")):
        value = (
            overrides.get(name, unit["placeholders"][name])
            if overrides
            else unit["placeholders"][name]
        )
        if delimit_commands and not name.startswith('MATHSEG_'):
            value = delimit_tex_control_word(value)
            if re.fullmatch(r"SPACE_[0-9]{4}", name) and value == "\\":
                # Legacy SPACE payloads leave their whitespace in source_text.
                # Keep a control space before translated prose or a wrapper.
                whitespace = (" ", "\t", "\r", "\n")
                source_following = unit["source_text"].partition(f"<{name}>")[2]
                if source_following[:1] not in whitespace:
                    raise RecordError(f"{name}: legacy control space needs source whitespace")
                following = rendered.partition(f"<{name}>")[2]
                if following[:1] not in whitespace:
                    value += " "
        rendered = rendered.replace(f"<{name}>", value, 1)
    return rendered


def delimit_tex_control_word(value: str) -> str:
    """Render-only lexical separator, consumed by TeX after a control word."""
    match = re.search(r"(\\+)[A-Za-z]+\Z", value)
    if match and len(match.group(1)) % 2:
        return value + " "
    return value


def placeholder_names(text: str) -> list[str]:
    return PLACEHOLDER_TOKEN_RE.findall(text)


FONT_WRAPPER_RE = re.compile(r"<(?:TEXTIT|TEXTBF|TEXTSF|TEXTTT|TEXTSC|TEXTRM|EMPH|TEXT)(?:OPEN|CLOSE)_[0-9]{4}>")
FONT_OPEN_RE = re.compile(r"(?:\{\\(?:it|bf|rm|sf|tt|sc)\s*|\{\s*\\em\s*|\\(?:textit|textbf|textsf|texttt|textsc|textrm|emph|text)\{)")
TEXT_ACCENT_TOKEN_RE = re.compile(r"<ACCENT_[0-9]{4}>")
TEXT_ACCENT_PAYLOAD_RE = re.compile(r'''\\(['`"])[ \t\r\n]*(?:\{([A-Za-z])\}|([A-Za-z]))''')


def is_font_wrapper(token: str, placeholders: Mapping[str, str]) -> bool:
    if not FONT_WRAPPER_RE.fullmatch(token):
        return False
    name = token[1:-1]
    payload = placeholders.get(name, "")
    return payload == "}" if "CLOSE_" in name else bool(FONT_OPEN_RE.fullmatch(payload))


def term_display_text(text: str, placeholders: Mapping[str, str]) -> str:
    """Visible prose only; preserve raw values and all semantic math nodes."""
    def accent(match: re.Match[str]) -> str:
        payload = placeholders.get(match.group(0)[1:-1], "")
        parsed = TEXT_ACCENT_PAYLOAD_RE.fullmatch(payload)
        if parsed is None:
            return match.group(0)
        combining = {"'": "\u0301", "`": "\u0300", '"': "\u0308"}[parsed[1]]
        return unicodedata.normalize("NFC", (parsed[2] or parsed[3]) + combining)
    text = TEXT_ACCENT_TOKEN_RE.sub(accent, text)
    return FONT_WRAPPER_RE.sub(lambda match: "" if is_font_wrapper(match.group(0), placeholders) else match.group(0), text)


def validate_tex_controls(unit: dict[str, Any], candidate: dict[str, Any]) -> list[str]:
    """Reject every unprotected TeX control in source and translated prose."""
    errors = []
    for field, text in (("source_text", unit.get("source_text", "")), ("translation", candidate.get("translation", ""))):
        if not isinstance(text, str):
            errors.append(f"{unit.get('unit_id')}: {field} must be a string")
            continue
        if re.search(r"\\(?:[A-Za-z@]+|.)|[%#$&_^~{}]", PLACEHOLDER_TOKEN_RE.sub("", text)):
            errors.append(f"{unit.get('unit_id')}: {field} contains unprotected TeX controls")
    from .math_text import validate_translation
    if isinstance(candidate.get('translation'), str):
        errors.extend(validate_translation(unit, candidate['translation']))
    return errors


def _validate_unit(unit: dict[str, Any], source_commit: str) -> list[str]:
    errors: list[str] = []
    location = unit.get("_record_location", "unit")
    schema_value = {key: value for key, value in unit.items() if not key.startswith("_")}
    errors.extend(validate_named_schema(schema_value, "unit.schema.json", str(location)))
    required_strings = (
        "unit_id",
        "parent_tag",
        "chapter",
        "node_kind",
        "risk_level",
        "source_commit",
        "source_text",
        "source_text_hash",
        "source_structure_hash",
        "source_math_hash",
        "source_status",
    )
    for key in required_strings:
        if not isinstance(unit.get(key), str) or not unit[key]:
            errors.append(f"{location}: {key} must be a non-empty string")
    if type(unit.get('schema_version')) is not int or unit.get("schema_version") not in {1, 2, 3}:
        errors.append(f"{location}: unit schema_version must be 1, 2 or 3")
    if unit.get("source_commit") != source_commit:
        errors.append(f"{location}: source_commit does not match upstream.lock")
    if unit.get("source_status") != "CURRENT":
        errors.append(f"{location}: pilot validator only accepts source_status CURRENT")
    if unit.get("risk_level") not in {"R0", "R1", "R2", "R3"}:
        errors.append(f"{location}: invalid risk_level {unit.get('risk_level')!r}")
    placeholders = unit.get("placeholders")
    if not isinstance(placeholders, dict):
        errors.append(f"{location}: placeholders must be an object")
        placeholders = {}
    for key, value in placeholders.items():
        if not isinstance(key, str) or not PLACEHOLDER_NAME_RE.fullmatch(key):
            errors.append(f"{location}: invalid placeholder name {key!r}")
        if not isinstance(value, str) or not value:
            errors.append(f"{location}: placeholder {key!r} must have non-empty TeX")
    source_placeholders = placeholder_names(str(unit.get("source_text", "")))
    if len(source_placeholders) != len(set(source_placeholders)):
        errors.append(f"{location}: source_text repeats a placeholder name")
    if set(source_placeholders) != set(placeholders):
        errors.append(
            f"{location}: placeholder object keys must match source_text tokens "
            f"({sorted(placeholders)!r} != {sorted(set(source_placeholders))!r})"
        )
    render = unit.get("render")
    if not isinstance(render, dict):
        errors.append(f"{location}: render must be an object")
    else:
        for key in ("prefix", "suffix"):
            if not isinstance(render.get(key), str):
                errors.append(f"{location}: render.{key} must be a string")
    if all(isinstance(unit.get(key), str) for key in (
        "source_text_hash",
        "source_structure_hash",
        "source_math_hash",
    )):
        from .math_text import validate_regions
        math_errors = validate_regions(unit) if unit.get('schema_version') in {1, 2, 3} else []
        errors.extend(f'{location}: {e}' for e in math_errors)
        try:
            expected = expected_unit_hashes(unit)
        except (ValueError, KeyError, TypeError, IndexError) as exc:
            errors.append(f'{location}: cannot validate source hashes: {exc}')
            return errors
        for key, value in expected.items():
            if unit.get(key) != value:
                errors.append(f"{location}: {key} mismatch; run stamp-units")
            elif not HASH_RE.fullmatch(value):
                errors.append(f"{location}: malformed {key}")
    return errors


def _validate_candidate(
    candidate: dict[str, Any], unit: dict[str, Any], source_commit: str
) -> list[str]:
    errors: list[str] = []
    location = candidate.get("_record_location", "candidate")
    required_strings = (
        "unit_id",
        "source_commit",
        "source_text_hash",
        "model_id",
        "model_lane",
        "reasoning_effort",
        "prompt_version",
        "glossary_revision",
        "context_hash",
        "translation",
        "stage",
        "source_status",
        "qa_status",
        "term_status",
        "publication_status",
        "created_at",
    )
    for key in required_strings:
        if not isinstance(candidate.get(key), str) or not candidate[key]:
            errors.append(f"{location}: {key} must be a non-empty string")
    schema_version = candidate.get("schema_version")
    if schema_version not in {1, 2}:
        errors.append(f"{location}: schema_version must be 1 or 2")
    if schema_version == 2:
        schema_value = {
            key: value for key, value in candidate.items() if not key.startswith("_")
        }
        errors.extend(
            validate_named_schema(schema_value, "candidate.schema.json", str(location))
        )
        provenance_strings = (
            "harness_id",
            "harness_version",
            "model_record_id",
            "run_id",
            "model_identity_confidence",
        )
        for key in provenance_strings:
            if not isinstance(candidate.get(key), str) or not candidate[key]:
                errors.append(f"{location}: {key} must be a non-empty string for schema v2")
        if "model_snapshot" not in candidate:
            errors.append(f"{location}: model_snapshot is required for schema v2")
        if candidate.get("model_identity_confidence") not in {
            "runtime-resolved",
            "owner-confirmed",
            "declared",
            "unknown",
        }:
            errors.append(f"{location}: invalid model_identity_confidence")
        translation = candidate.get("translation")
        if isinstance(translation, str):
            expected_translation_hash = sha256_value(translation)
            if candidate.get("translation_hash") != expected_translation_hash:
                errors.append(f"{location}: translation_hash mismatch")
    elif "translation_hash" in candidate and candidate.get("translation_hash") != sha256_value(candidate.get("translation", "")):
        errors.append(f"{location}: translation_hash mismatch")
    if candidate.get("source_commit") != source_commit:
        errors.append(f"{location}: source_commit does not match upstream.lock")
    if candidate.get("source_text_hash") != unit.get("source_text_hash"):
        errors.append(f"{location}: source_text_hash does not match unit")
    lane = candidate.get("model_lane")
    if not isinstance(lane, str) or not MODEL_LANE_RE.fullmatch(lane) or ".." in lane:
        errors.append(f"{location}: invalid model_lane {lane!r}")
    context = candidate.get("context")
    if not isinstance(context, dict):
        errors.append(f"{location}: context must be an object")
    elif candidate.get("context_hash") != sha256_value(context):
        errors.append(f"{location}: context_hash mismatch")
    unknown_terms = candidate.get("unknown_terms")
    if not isinstance(unknown_terms, list):
        errors.append(f"{location}: unknown_terms must be an array")
        unknown_terms = []
    else:
        for index, term in enumerate(unknown_terms):
            if not isinstance(term, dict) or not all(
                isinstance(term.get(key), str) and term[key]
                for key in ("source_term", "target_term", "context")
            ):
                errors.append(
                    f"{location}: unknown_terms[{index}] requires source_term, "
                    "target_term, and context"
                )
    notes = candidate.get("notes")
    if not isinstance(notes, list) or not all(isinstance(note, str) for note in notes):
        errors.append(f"{location}: notes must be an array of strings")
    term_occurrences = candidate.get("term_occurrences")
    valid_term_occurrences: list[dict[str, str]] = []
    if not isinstance(term_occurrences, list):
        errors.append(f"{location}: term_occurrences must be an array")
    else:
        for index, occurrence in enumerate(term_occurrences):
            if not isinstance(occurrence, dict) or not all(
                isinstance(occurrence.get(key), str) and occurrence[key]
                for key in ("source_term", "target_term")
            ):
                errors.append(
                    f"{location}: term_occurrences[{index}] requires source_term "
                    "and target_term"
                )
                continue
            source_term = occurrence["source_term"]
            target_term = occurrence["target_term"]
            if "（" in source_term or "）" in source_term or "（" in target_term or "）" in target_term:
                errors.append(
                    f"{location}: term_occurrences[{index}] values must not contain "
                    "full-width parentheses"
                )
                continue
            valid_term_occurrences.append(occurrence)
    source_tokens = placeholder_names(str(unit.get("source_text", "")))
    translation = candidate.get("translation")
    if isinstance(translation, str):
        target_tokens = placeholder_names(translation)
        if target_tokens != source_tokens:
            errors.append(
                f"{location}: protected placeholders changed or reordered "
                f"({target_tokens!r} != {source_tokens!r})"
            )
        without_tokens = PLACEHOLDER_TOKEN_RE.sub("", translation)
        if re.search(r"\\[A-Za-z@]+|\$", without_tokens):
            errors.append(f"{location}: translation contains raw protected TeX")
        display_text = term_display_text(translation, unit["placeholders"])
        term_literals = [
            term_display_text(f"{occurrence['target_term']}（{occurrence['source_term']}）", unit["placeholders"])
            for occurrence in valid_term_occurrences
        ]
        cursor = 0
        for index, literal in enumerate(term_literals):
            position = display_text.find(literal, cursor)
            if position < 0:
                errors.append(
                    f"{location}: term_occurrences[{index}] is missing or out of order: {literal}"
                )
                break
            cursor = position + len(literal)
        for literal in set(term_literals):
            expected_count = term_literals.count(literal)
            actual_count = display_text.count(literal)
            if actual_count != expected_count:
                errors.append(
                    f"{location}: bilingual term count mismatch for {literal}: "
                    f"recorded {expected_count}, found {actual_count}"
                )
        residue_text = display_text
        for literal in term_literals:
            residue_text = residue_text.replace(literal, "", 1)
        residue_text = PLACEHOLDER_TOKEN_RE.sub("", residue_text)
        allowed = candidate.get("allowed_english", [])
        if not isinstance(allowed, list) or not all(isinstance(word, str) for word in allowed):
            errors.append(f"{location}: allowed_english must be an array of strings")
            allowed = []
        residue = sorted({word for word in ASCII_WORD_RE.findall(residue_text) if word not in allowed})
        if residue:
            errors.append(f"{location}: unexplained English residue: {', '.join(residue)}")
    stage = candidate.get("stage")
    if stage not in STAGES:
        errors.append(f"{location}: invalid stage {stage!r}")
    elif stage == "CRITIC_OK":
        errors.append(
            f"{location}: CRITIC_OK is unavailable until critic records and validation are implemented"
        )
    elif STAGES.index(stage) > MODEL_MAX_STAGE:
        errors.append(f"{location}: model candidate cannot claim stage {stage}")
    if candidate.get("source_status") != "CURRENT":
        errors.append(f"{location}: candidate source_status must be CURRENT")
    if candidate.get("qa_status") not in {"NOT_RUN", "PASS", "FAIL"}:
        errors.append(f"{location}: invalid qa_status")
    if stage in {"STRUCTURE_OK", "TERM_OK", "CRITIC_OK"} and candidate.get("qa_status") != "PASS":
        errors.append(f"{location}: stage {stage} requires qa_status PASS")
    term_status = candidate.get("term_status")
    if term_status not in {"CLEAR", "DECISION_REQUIRED"}:
        errors.append(f"{location}: invalid term_status")
    if unknown_terms and term_status != "DECISION_REQUIRED":
        errors.append(f"{location}: unknown terms require DECISION_REQUIRED")
    if unknown_terms and stage in {"TERM_OK", "CRITIC_OK"}:
        errors.append(f"{location}: unresolved terms prevent stage {stage}")
    if not unknown_terms and term_status == "DECISION_REQUIRED":
        errors.append(f"{location}: DECISION_REQUIRED needs at least one unknown term")
    occurrence_pairs = {
        (occurrence["source_term"], occurrence["target_term"])
        for occurrence in valid_term_occurrences
    }
    for term in unknown_terms:
        if isinstance(term, dict) and all(
            isinstance(term.get(key), str) for key in ("source_term", "target_term")
        ) and (term["source_term"], term["target_term"]) not in occurrence_pairs:
            errors.append(
                f"{location}: unknown term {term['target_term']}（{term['source_term']}） "
                "has no matching term_occurrences entry"
            )
    if candidate.get("publication_status") not in {"INTERNAL", "CANDIDATE"}:
        errors.append(f"{location}: model candidate cannot be RELEASED")
    if candidate.get("review_claims") not in (None, []):
        errors.append(f"{location}: candidate must not contain human review claims")
    return errors


def _require_string(record: dict[str, Any], key: str) -> str:
    value = record.get(key)
    if not isinstance(value, str):
        raise RecordError(f"{key} must be a string")
    return value
